public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] messageBytes = schema.toByteArray(message, buffer);
    int size = messageBytes.length;
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(messageBytes, 0, size);
    return size + 4; // 4 bytes for the length prefix
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    return schema.writeTo(out, message, buffer) + 4;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int length = schema.serializedSize(message);
    buffer = ensurecapacity(buffer, length);
    LittleEndianDataOutputStream dos = buffer.out;
    dos.writeInt(length);
    schema.writeTo(dos, message, buffer);
    buffer.roll();
    return length + 4;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] messageBytes = schema.toByteArray(message);
    int messageLength = messageBytes.length;
    int size = CodedOutputStream.computeRawVarint32Size(messageLength) + messageLength;
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
    codedOut.writeRawVarint32(messageLength);
    codedOut.writeRawBytes(messageBytes, 0, messageLength);
    codedOut.flush();
    out.write(buffer.getData(), 0, size);
    out.flush();
    return size;
}

