public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity <= 1) {
            return 2;
        }
        int candidate = desiredCapacity + (desiredCapacity < 1000 ? 1 : (desiredCapacity / 10));
        while (!isPrime(candidate)) {
            candidate++;
        }
        return candidate;
    }

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) return 2;
    if (desiredCapacity % 2 == 0) desiredCapacity++;
    while (!isPrime(desiredCapacity)) {
        desiredCapacity += 2;
        if (desiredCapacity >= 1000 && desiredCapacity > desiredCapacity * 0.89) break;
    }
    return desiredCapacity;
}

public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    while (!isPrime(capacity)) {
        capacity++;
    }
    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    int capacity = desiredCapacity;
    boolean found = false;

    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
        }
    }

    if (desiredCapacity >= 1000) {
        while ((double) capacity / desiredCapacity > 1.11) {
            capacity++;
        }
    }

    return capacity;
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

