public GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    LinkedList<E> edges = new LinkedList<>(tour);
    LinkedList<V> vertices = new LinkedList<>();
    Iterator<E> iterator = edges.iterator();
    V startVertex = graph.getEdgeSource(iterator.next());
    vertices.add(startVertex);

    while (iterator.hasNext()){
        E edge = iterator.next();
        V nextVertex = graph.getEdgeTarget(edge);
        vertices.add(nextVertex);
    }

    return new GraphPathImpl<>(graph, startVertex, vertices, edges, edges.size());
}

