private void pop(final String descriptor){
    int numToPop = 0;
    for (char c : descriptor.toCharArray()) {
        if (c == 'L' || c == '[') {
            while (descriptor.charAt(++numToPop) != ';');
        } else if (c == '(') {
            numToPop = descriptor.indexOf(')', numToPop) + 1;
        }
    }
    // Pop the types from the stack
    for (int i = 0; i < numToPop; i++) {
        this.outputFrameStack.pop();
    }
}

void function ( Stack<AbstractType> frameStack, String descriptor ) {
    int count = 1;
    if (descriptor.startsWith "(")) {
        while (descriptor.charAt(count) != ')') {
            if (descriptor.charAt(count) == 'L' || descriptor.charAt(count) == '[') {
                while (descriptor.charAt(count) == '[') count++;
                int semiColonIndex = descriptor.indexOf(';', count);
                if (semiColonIndex == -1) throw new IllegalArgumentException("Invalid descriptor");
                count = semiColonIndex + 1;
            } else {
                count++;
            }
        }
    }
    while (count > 0) {
        frameStack.pop();
        count--;
    }
}

private void pop(final String descriptor) {
    Type type = Type.getType(descriptor);
    if (type.getSort() == Type.VOID) {
        // Do nothing for void
    } else if (type.getSort() == Type.ARRAY) {
        // Pop array elements
        pop(type.getElementType());
        pop(); // Pop array reference
    } else if (type.getSort() == Type.METHOD) {
        // Pop method arguments
        for (Type argumentType : type.getArgumentTypes()) {
            pop(argumentType);
        }
        // Pop method return value
        pop();
    } else {
        // Pop scalar type
    }
}

